# Load all grids from the session to see what we have
import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

def parse_grid(text, expected_h=None):
    lines = text.strip().split('\n')
    if expected_h:
        return [[int(x) for x in line.split()] for line in lines[:expected_h]]
    return [[int(x) for x in line.split()] for line in lines]

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    grid_text = t[m.end():].split('\n')[0:h]
    rows = [r.split() for r in grid_text]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Keys:", sorted(G.keys()))
if G:
    print("\nDemo inputs/outputs:")
    for k in sorted(G.keys())[:5]:
        print(f"\n{k}: {k!r}")
        if isinstance(G[k], list) and len(G[k]) > 0 and not isinstance(G[k][0], list):
            # Scalar/int - show it
            print("  ", G[k])
        else:
            print("  Input shape:", len(G[k]), "x", len(G[k][0]) if G[k] else 0)
            print("  Output shape:", len(G[k][1]) if len(G[k]) > 1 and isinstance(G[k][1], list) else "N/A")

