def count_neighbors(grid, i, j):
    """Count orthogonally adjacent 1s"""
    count = 0
    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        ni, nj = i + di, j + dj
        if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == 1:
            count += 1
    return count

def has_2d_neighbors(grid, i, j):
    """Count in both directions (including diagonals as 2D block)"""
    count = 0
    for di in [-1, 0, 1]:
        for dj in [-1, 0, 1]:
            if di != 0 or dj != 0:
                ni, nj = i + di, j + dj
                if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == 1:
                    count += 1
    return count

