    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

def find_components(grid):
    visited = set()
    h, w = len(grid), len(grid[0])

    def dfs(i, j):
        stack = [(i, j)]
        comp = []
        while stack:
            ci, cj = stack.pop()
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = ci + di, cj + dj
                if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == 0 and (ni, nj) not in visited:
                    visited.add((ni, nj))
                    stack.append((ni, nj))
                    comp.append((ni, nj))
        return comp

    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0 and (i, j) not in visited:
                visited.add((i, j))
                dfs(i, j)

    return list(visited)

